<script setup>
import { computed } from 'vue'
const props = defineProps({ flights: { type: Array, required: true } })
const points = [{ code: 'JFK', x: 57, y: 42 }, { code: 'LHR', x: 50, y: 34 }, { code: 'CDG', x: 54, y: 39 }, { code: 'DUB', x: 47, y: 31 }, { code: 'HND', x: 86, y: 46 }, { code: 'ORD', x: 48, y: 39 }, { code: 'MAD', x: 53, y: 45 }, { code: 'BOS', x: 60, y: 36 }]
const routes = computed(() => props.flights.map((flight, index) => ({ flight, origin: points.find((point) => point.code === flight.origin) || points[0], destination: points.find((point) => point.code === flight.destination) || points[1], bend: index % 2 ? -6 : 7 })))
</script>
<template>
  <div class="route-graphic"><svg viewBox="0 0 100 78" role="img" aria-label="Schematic route map of active airline flights"><defs><pattern id="map-grid" width="4" height="4" patternUnits="userSpaceOnUse"><path d="M 4 0 L 0 0 0 4" fill="none" stroke="#d9e5da" stroke-width=".12" /></pattern></defs><rect width="100" height="78" fill="url(#map-grid)" /><path class="land-shape" d="M10 18l8-7 7 1 3 5 9 1 3 5-3 6 6 4-2 7-8 2-2 8-8 4-5-6-8-3-3-9 4-7-4-6zm34-4l8-5 10 3 3 5 9-2 6 7 7 2 1 6-6 4 1 6-5 5-9-3-5 5-7-4-9 2-4-6 2-7-5-5 4-7zm-13 33l9 1 3 5-5 8-6 4-6-4 1-8z" /><g v-for="route in routes" :key="route.flight.id"><path class="route-line" :class="{ 'route-delayed': route.flight.status === 'Delayed' }" :d="`M ${route.origin.x} ${route.origin.y} Q ${(route.origin.x + route.destination.x) / 2} ${(route.origin.y + route.destination.y) / 2 + route.bend} ${route.destination.x} ${route.destination.y}`" /><circle class="route-point" :cx="route.origin.x" :cy="route.origin.y" r=".65" /><circle class="route-point route-end" :cx="route.destination.x" :cy="route.destination.y" r=".65" /><text class="route-code" :x="route.origin.x + 1" :y="route.origin.y + 2">{{ route.origin.code }}</text><text class="route-code" :x="route.destination.x + 1" :y="route.destination.y + 2">{{ route.destination.code }}</text></g></svg><div class="map-caption"><span><i></i> ACTIVE ROUTES</span><b>{{ flights.length }} FLIGHTS</b></div></div>
</template>